export const getMaterialIconPath = (name: string): string => {
  const clean = (name || "").replace(/[{}]/g, "").trim().toLowerCase();
  let iconName = clean;
  if (iconName === "manage_search") iconName = "search";
  if (iconName === "hard_drive") iconName = "storage";
  if (iconName === "expand_more") iconName = "keyboard_arrow_down";
  if (iconName === "expand_less") iconName = "keyboard_arrow_up";
  if (iconName === "person_filled") iconName = "person";
  if (iconName === "report_problem") iconName = "warning";
  return materialIconPaths[iconName] || materialIconPaths["warning"] || "";
};
